// Renders the complete book PDF from JavaScript_Mastery_Complete_Manuscript.md (never from chapter PDFs).
// Reuses the master design system read-only: its Markdown renderer (lib/md.mjs), tokens, fonts and book.css.
// Book-level additions live in this folder (book-extension.css): title page, table of contents, one named page per
// chapter (so the running header changes with every chapter), short running titles, continuous page numbers.
// Two passes: pass 1 prints the book, the PDF outline (bookmarks, generated by Chrome from the headings) gives the
// exact page of every heading; pass 2 prints again with those numbers in the table of contents. A third pass runs
// only if the numbers moved.
// Usage: node build/render-pdf.mjs        (run from book-output/final-edition)
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const BUILD = path.dirname(fileURLToPath(import.meta.url));
const FINAL = path.resolve(BUILD, '..');
const WORK = path.join(BUILD, 'work');
const SYSTEM = path.resolve(FINAL, '..', 'master-design-system');
const lib = (f) => import(pathToFileURL(path.join(SYSTEM, 'scripts', 'lib', f)).href);
const { tokens, book: bookMeta, rules, fontFaceCss, fill, findChrome, toBn } = await lib('tokens.mjs');
const { blocks, inline, esc } = await lib('md.mjs');
const { readOutline } = await import(pathToFileURL(path.join(BUILD, 'pdf-outline.mjs')).href);

const book = JSON.parse(fs.readFileSync(path.join(WORK, 'book.json'), 'utf8'));
const manuscript = fs.readFileSync(path.join(FINAL, book.manuscript), 'utf8');
const OUT_PDF = path.join(FINAL, 'JavaScript_Mastery_Complete.pdf');

// ---------- split the manuscript into its parts ----------
const parts = [];
for (const chunk of manuscript.split(/^<!-- jsm:part /m).slice(1)) {
  const head = /^([^\n]*?)-->\n/.exec(chunk);
  const attrs = Object.fromEntries([...head[1].matchAll(/(\w+)=(\S+)/g)].map((m) => [m[1], m[2]]));
  parts.push({ ...attrs, md: chunk.slice(head[0].length).trim() });
}
const chapterMeta = new Map(book.chapters.map((c) => [c.id, c]));

// ---------- HTML ----------
const absImages = (html) => html.replace(/<img src="([^"]+)"/g, (_, src) => `<img data-src="${src}" src="${pathToFileURL(path.resolve(FINAL, src)).href}"`);
const cssString = (s) => `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
const pageRules = [];

function chapterHtml(part) {
  const c = chapterMeta.get(part.id);
  const lines = part.md.split('\n');
  const h1 = new RegExp(rules.titlePattern).exec(lines[0]);
  const [, chapNo, title] = h1;
  const opts = { codeBlocks: [] };
  const sections = [];
  let k = 0;
  for (const chunk of lines.slice(1).join('\n').split(/\n(?=## )/)) {
    const m = /^## (.+)\n/.exec(chunk);
    if (!m) continue;
    const heading = m[1].trim();
    const cls = rules.sectionClasses.find((r) => new RegExp(r.match).test(heading))?.class ?? '';
    let html = blocks(chunk, opts);
    if (cls === 'mcq') html = html.replace(/<p><strong>প্রশ্ন [^<]*<\/strong>[\s\S]*?<\/p>\n<ul>[\s\S]*?<\/ul>/g, (q) => `<div class="mcq-item">${q}</div>`);
    if (cls === 'solutions') html = html.replace(/<p>(<strong>সমাধান [০-৯]+<\/strong>)/g, '<p class="sol">$1');
    if (cls === 'answers') html = html.replace(new RegExp(`<p>(<strong>${rules.mcq.quickKeyLabel}:</strong>)`), '<p class="quick-key">$1');
    k += 1;
    html = html.replace(/^<h2>/, `<h2 id="${c.id}-s${k}">`);
    sections.push({ cls, html: absImages(html) });
  }
  const opener = `<header class="opener"><div class="chap-num">${chapNo.padStart(2, '০')}</div><p class="chap-label">${bookMeta.chapterWord} ${chapNo}</p><h1 id="${c.id}">${inline(title)}</h1></header>`;
  const sec = (s) => `<section class="sec ${s.cls}">\n${s.html}\n</section>`;
  const startPage = `s${c.number}`, bodyPage = `c${c.number}`;
  pageRules.push(`@page ${startPage} { @top-left { content: none; } @top-right { content: none; } }`,
    `@page ${bodyPage} { @top-right { content: ${cssString(`${bookMeta.chapterWord} ${chapNo} · ${c.running}`)}; } }`);
  // The opener and the learning objectives share the first page, which has no running header.
  return `<div class="chapter part" data-chapter="${c.number}">
<div class="chapter-start" style="page: ${startPage}">${opener}\n${sec(sections[0])}</div>
<div class="chapter-body" style="page: ${bodyPage}">${sections.slice(1).map(sec).join('\n')}</div>
</div>`;
}

function matterHtml(part, pageName, runningRight) {
  let html = absImages(blocks(part.md, { codeBlocks: [] }));
  html = html.replace(/^<h1>/, `<h1 id="${part.id}">`);
  let k = 0;
  html = html.replace(/<h2>/g, () => `<h2 id="${part.id}-s${++k}">`);
  if (runningRight !== undefined) {
    pageRules.push(`@page ${pageName} { @top-right { content: ${runningRight ? cssString(runningRight) : 'none'}; } }`);
  }
  return `<div class="matter part ${part.kind} ${part.id}" style="page: ${pageName}">${html}</div>`;
}

function titleHtml(part) {
  const [title, subtitle, tagline, author, edition] = part.md.split('\n').filter((l) => l.trim()).map((l) => l.replace(/^# /, ''));
  return `<div class="title-page part" style="page: title"><div class="tp-top"><p class="tp-series">${inline(tagline)}</p></div>
<div class="tp-main"><h1 id="title-page">${inline(title)}</h1><p class="tp-sub">${inline(subtitle)}</p></div>
<div class="tp-bottom"><p class="tp-author">${inline(author)}</p><p class="tp-edition">${inline(edition)}</p></div></div>`;
}

function tocHtml(pages) {
  const pg = (id) => (pages ? toBn(pages.get(id) ?? '?') : '০০০০');
  const item = (cls, id, text) => `<li class="${cls}"><a href="#${id}"><span class="t">${text}</span><span class="fill"></span><span class="pg">${pg(id)}</span></a>`;
  const chapters = book.chapters.map((c) => `${item('toc-ch', c.id, `<b>${esc(c.label)}</b> ${inline(c.title)}`)}<ol>${c.h2.map((h, i) => `${item('toc-s', `${c.id}-s${i + 1}`, inline(h))}</li>`).join('')}</ol></li>`).join('\n');
  const back = book.back.map((b) => `${item('toc-ch toc-back', b.id, `<b>${esc(b.title)}</b>`)}</li>`).join('\n');
  pageRules.push(`@page toc { @top-right { content: "সূচিপত্র"; } }`);
  return `<div class="toc-page part" style="page: toc"><h1 id="toc">সূচিপত্র</h1><ol class="toc">${chapters}\n${back}</ol></div>`;
}

function buildHtml(pages) {
  pageRules.length = 0;
  const body = parts.map((p) => {
    if (p.kind === 'title') return titleHtml(p);
    if (p.kind === 'copyright') return matterHtml(p, 'plain');
    if (p.kind === 'toc') return tocHtml(pages);
    if (p.kind === 'chapter') return chapterHtml(p);
    if (p.kind === 'back') {
      const b = book.back.find((x) => x.id === p.id);
      return matterHtml(p, `p-${p.id}`, b.title);
    }
    return matterHtml(p, 'front', '');
  }).join('\n');
  const base = fill(fs.readFileSync(path.join(SYSTEM, 'templates', 'book.css'), 'utf8').replace('/*__FONTS__*/', fontFaceCss()),
    { running: { left: bookMeta.runningTitle, right: '' } });
  const ext = fill(fs.readFileSync(path.join(BUILD, 'book-extension.css'), 'utf8'));
  return `<!doctype html><html lang="bn"><head><meta charset="utf-8"><title>${esc(bookMeta.title)} — ${esc(bookMeta.subtitle)} | ${esc(bookMeta.author)}</title>
<style>${base}\n${ext}\n${pageRules.join('\n')}</style></head><body>${body}</body></html>`;
}

// ---------- print ----------
function print(html, pdfFile) {
  const htmlFile = path.join(WORK, 'book.html');
  fs.writeFileSync(htmlFile, html);
  const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'jsm-book-'));
  const started = Date.now();
  try {
    execFileSync(findChrome(), ['--headless', '--disable-gpu', '--no-first-run', `--user-data-dir=${profile}`, '--no-pdf-header-footer',
      '--generate-pdf-document-outline', `--print-to-pdf=${pdfFile}`, pathToFileURL(htmlFile).href], { stdio: 'pipe', timeout: 1_800_000 });
  } finally {
    try { fs.rmSync(profile, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 }); } catch { /* temp may linger */ }
  }
  return Math.round((Date.now() - started) / 1000);
}

// Expected bookmark order: every H1 (title page, front matter, TOC, chapters, appendices) and every H2.
const plain = (md) => inline(md).replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"');
function expectedHeadings() {
  const list = [];
  for (const p of parts) {
    if (p.kind === 'title') { list.push({ id: 'title-page', level: 1 }); continue; }
    if (p.kind === 'toc') { list.push({ id: 'toc', level: 1 }); continue; }
    if (p.kind === 'chapter') {
      const c = chapterMeta.get(p.id);
      list.push({ id: c.id, level: 1, text: plain(c.title) });
      c.h2.forEach((h, i) => list.push({ id: `${c.id}-s${i + 1}`, level: 2, text: plain(h) }));
      continue;
    }
    const h1 = /^# (.+)$/m.exec(p.md)[1];
    list.push({ id: p.id, level: 1, text: plain(h1) });
    [...p.md.matchAll(/^## (.+)$/gm)].forEach((m, i) => list.push({ id: `${p.id}-s${i + 1}`, level: 2, text: plain(m[1]) }));
  }
  return list;
}
function pageMap(outline) {
  const flat = outline.items.filter((i) => i.level <= 2);
  const want = expectedHeadings();
  if (flat.length !== want.length) throw new Error(`Outline has ${flat.length} H1/H2 bookmarks, expected ${want.length}`);
  const norm = (s) => s.replace(/\s+/g, ''); // a wrapped heading loses the space at its line break
  // Chrome occasionally repeats a heading's text in its bookmark title when the heading box is fragmented.
  const mismatch = want.filter((w, i) => w.text && !norm(flat[i].title).startsWith(norm(w.text)));
  if (mismatch.length) throw new Error(`Outline titles differ from the headings, first: ${mismatch[0].id} "${flat[want.indexOf(mismatch[0])].title}"`);
  return new Map(want.map((w, i) => [w.id, flat[i].page]));
}

const timings = [];
const pass1 = path.join(WORK, 'pass1.pdf');
timings.push(print(buildHtml(null), pass1));
let pages = pageMap(readOutline(pass1));
timings.push(print(buildHtml(pages), OUT_PDF));
let outline = readOutline(OUT_PDF);
let check = pageMap(outline);
let moved = [...check].filter(([id, p]) => pages.get(id) !== p).length;
if (moved) {
  pages = check;
  timings.push(print(buildHtml(pages), OUT_PDF));
  outline = readOutline(OUT_PDF);
  check = pageMap(outline);
  moved = [...check].filter(([id, p]) => pages.get(id) !== p).length;
}
fs.rmSync(pass1, { force: true });
const chapterStarts = Object.fromEntries(book.chapters.map((c) => [c.number, check.get(c.id)]));
const data = {
  pdf: path.basename(OUT_PDF), pages: outline.pages, bytes: fs.statSync(OUT_PDF).size, passes: timings.length, secondsPerPass: timings,
  tocStable: moved === 0, bookmarks: outline.items.length, bookmarksLevel1: outline.items.filter((i) => i.level === 1).length,
  chapterStarts, backStarts: Object.fromEntries(book.back.map((b) => [b.id, check.get(b.id)])), tocPage: check.get('toc'),
};
fs.writeFileSync(path.join(WORK, 'pdf-data.json'), JSON.stringify(data, null, 2) + '\n');
console.log(`PDF ${data.pdf}: ${data.pages} pages, ${(data.bytes / 1048576).toFixed(1)} MB, ${data.bookmarks} bookmarks, passes ${data.passes} (${timings.join('s, ')}s), TOC stable: ${data.tocStable}`);
